import pyomo.environ as pyo

DATA = {
    "CATALYSTS": ["palladium_heavy", "platinum_heavy"],
    # resource usage and yield per unit of each catalyst
    "platinum_required": {
        "palladium_heavy": 15,
        "platinum_heavy": 20,
    },
    "palladium_required": {
        "palladium_heavy": 25,
        "platinum_heavy": 14,
    },
    "conversion_rate": {
        "palladium_heavy": 5,
        "platinum_heavy": 4,
    },
    # available resources
    "platinum_available": 450,
    "palladium_available": 390,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Set: the two catalyst options
    model.CATALYSTS = pyo.Set(initializer=list(d["CATALYSTS"]))

    # Variable: number of each catalyst used (scalable activity level, continuous)
    model.x = pyo.Var(model.CATALYSTS, within=pyo.NonNegativeReals)

    # Objective: maximise total CO2 conversion rate (units per second)
    def obj_rule(m):
        return sum(d["conversion_rate"][c] * m.x[c] for c in m.CATALYSTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: platinum consumed must not exceed platinum available
    def platinum_limit_rule(m):
        return sum(d["platinum_required"][c] * m.x[c] for c in m.CATALYSTS) \
            <= d["platinum_available"]

    model.platinum_limit = pyo.Constraint(rule=platinum_limit_rule)

    # Constraint: palladium consumed must not exceed palladium available
    def palladium_limit_rule(m):
        return sum(d["palladium_required"][c] * m.x[c] for c in m.CATALYSTS) \
            <= d["palladium_available"]

    model.palladium_limit = pyo.Constraint(rule=palladium_limit_rule)

    return model
